grid:




		[#FIELDS#]




			[#VIEW#]







	select 'active$&Identity;Grid$(this);' as message
	return






	select 'dispose$&Identity;Grid$(this);' as message
	return








function active$&Identity;Grid$(g) {	
	g.add_itemValueChanged(onChange$&Identity;Grid$);
	g.add_onResponseComplete(on$&Identity;Grid$ResponseComplete);
	g.add_commandEvent(on$&Identity;Grid$ExecuteCommand);

	g.$a = {
		//tien: '[tien]:=[so_luong] - [gia]'
	}
	g.$h = []; 
}
function dispose$&Identity;Grid$(g) {
	g.$a = null; 
	try {g.remove_itemValueChanged(onChange$&Identity;Grid$);} catch (ex) {}		
	try {g.remove_onResponseComplete(on$&Identity;Grid$ResponseComplete);} catch (ex) {}
	try {g.remove_commandEvent(on$&Identity;Grid$ExecuteCommand);} catch (ex) {}
} 

function on$&Identity;Grid$ResponseComplete(sender, e) {
	var g = e.object, context = e.type.Context, result = e.type.Result, o = e.type.Object, f = g.get_element().parentForm;
	switch (context) {
		case '':
			break;
		default:
			break;
	}
}
function onChange$&Identity;Grid$(sender, eventArgs) {
	var o = eventArgs.get_object(), g = o.grid, f = g.get_element().parentForm, name = o.field.Name;
	switch (name) { 
		//case '':
		//	g.validExpression(o, [g.$a.tien]);
		//	break; 
		default:
			break;
	}
} 

function on$&Identity;Grid$ExecuteCommand(sender, e) {
	var action = e.type.Action, g = sender, f = g.get_element().parentForm; 
	switch (action) {
		case 'AfterInsertRow':
			break;
		case 'AfterRemoveRow':  
			break; 

		default:
			break;
	}
}  


















